    const transport = createRuntimeTransport(
      { location: "managed", runnerPublicKey },
      {
        apiClient: apiClient(),
        encryptedRequest: vi.fn(),
        connectEncrypted,
      },
    );

    await expect(transport.get("/api/repos")).rejects.toThrow(
