                <code className="break-all text-gray-200">{test.command}</code>
                <span className="ml-2 text-gray-500">{test.status}</span>
                {test.summary ? (
                  <p className="break-words text-xs text-gray-500">{test.summary}</p>
                ) : null}
              </li>
            ))}
          </ul>
        </div>
      ) : null}
    </section>
